typedef struct { V p, d; } R;

V add(V a, V b) { return (V){a.x+b.x, a.y+b.y, a.z+b.z}; }
V sub(V a, V b) { return (V){a.x-b.x, a.y-b.y, a.z-b.z}; }
V mul(V a, float t) { return (V){a.x*t, a.y*t, a.z*t}; }
float dot(V a, V b) { return a.x*b.x + a.y*b.y + a.z*b.z; }
V norm(V a) { float l = sqrt(dot(a,a)); return mul(a, l>1e-5f ? 1.0f/l : 1.0f); }

int hit_sphere(V c, float r, R ray, float *t) {
    V oc = sub(ray.p, c);
    float a = dot(ray.d, ray.d);
    float b = 2.0f * dot(oc, ray.d);
    float cc = dot(oc, oc) - r*r;
    float disc = b*b - 4*a*cc;
    if (disc < 0) return 0;
    float sq = sqrt(disc);
    float t1 = (-b - sq) / (2*a);
    if (t1 > 1e-3f) { *t = t1; return 1; }
    float t2 = (-b + sq) / (2*a);
    if (t2 > 1e-3f) { *t = t2; return 1; }
    return 0;
}

V trace(R r, V sph_c, float sph_r) {
    float t;

    if (hit_sphere(sph_c, sph_r, r, &t)) {
        return (V){51.0f/255, 10.0f/255, 10.0f/255};
    }

    if (r.d.y < -1e-4f) {
        float gt = (-1000.0f - r.p.y) / r.d.y;
        if (gt > 1e-3f) {
            V hit = add(r.p, mul(r.d, gt));
            int cx = ((int)(hit.x / 300.0f)) & 1;
            int cz = ((int)(hit.z / 300.0f)) & 1;
            if (cx ^ cz) return (V){152.0f/255, 152.0f/255, 152.0f/255};
            else return (V){67.0f/255, 67.0f/255, 67.0f/255};
        }
    }

    float dx_cam = r.d.x / (r.d.z + 1e-5f);
    float x_norm = dx_cam / 1200.0f;
    float r_sky = 189.0f - 955.6f * r.d.y + 13.0f * x_norm * x_norm;
    float g_sky = 213.0f - 511.1f * r.d.y;

    return (V){fminf(255, fmaxf(0, r_sky))/255, fminf(255, fmaxf(0, g_sky))/255, 1.0f};
}

int main() {
    int w = 2400, h = 1800;
    FILE *f = fopen("reconstructed.ppm", "w");
    fprintf(f, "P3\n%d %d\n255\n", w, h);

    V cam = {1200.0f, 50.0f, 5000.0f};
    V sph_c = {1200.0f, 1050.0f, 2000.0f};
    float sph_r = 150.0f;

    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            float px = (x - w/2.0f) * 0.5f;
            float py = (h/2.0f - y) * 0.5f;
            V target = {cam.x + px, cam.y + py, cam.z - 5000.0f};
            R ray = {cam, norm(sub(target, cam))};
            V col = trace(ray, sph_c, sph_r);
            fprintf(f, "%d %d %d\n", (int)(col.x*255), (int)(col.y*255), (int)(col.z*255));
        }
    }
    fclose(f);
    return 0;
}
